solution.python:
import sys

oxirgi = {}
for satr in sys.stdin.read().split("\n"):
    if not satr.strip():
        continue
    summa, yol = satr.split()
    summa = int(summa)
    kanallar = yol.split(">")
    for k in kanallar:
        oxirgi.setdefault(k, 0)
    oxirgi[kanallar[0]] += summa

for k in sorted(oxirgi):
    print(f"{k}: first click {oxirgi[k]}")

solution.java:
import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        TreeMap<String, Long> oxirgi = new TreeMap<>();
        while (in.hasNext()) {
            long summa = in.nextLong();
            String[] kanallar = in.next().split(">");
            for (String k : kanallar) {
                oxirgi.putIfAbsent(k, 0L);
            }
            oxirgi.merge(kanallar[0], summa, Long::sum);
        }
        for (Map.Entry<String, Long> e : oxirgi.entrySet()) {
            System.out.println(e.getKey() + ": first click " + e.getValue());
        }
    }
}

solution.cpp:
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

int main() {
    map<string, long long> oxirgi;
    long long summa;
    string yol;
    while (cin >> summa >> yol) {
        vector<string> kanallar;
        stringstream ss(yol);
        string k;
        while (getline(ss, k, '>')) kanallar.push_back(k);
        for (auto& x : kanallar) {
            oxirgi[x] += 0;
        }
        oxirgi[kanallar.front()] += summa;
    }
    for (auto& [k, v] : oxirgi) cout << k << ": first click " << v << "\n";
    return 0;
}
